zenPage.getComponentById('comp').focus();
var env = zenPage.getComponentById('labelEnv').getValue();
if (env == 'DEV')
{
	// User can select environemnt
	zenPage.getComponentById('fsEnv').setProperty('hidden', false);
	var radEnv = zenPage.getComponentById('envRS').getValue();
	zenPage.getComponentById('butSvn').setProperty('caption','Load from ' + radEnv + ' SubVersion');
}
else
{
	// User can not change the Environment
	zenPage.getComponentById('envRS').setValue(env)	;
	zenPage.getComponentById('butSvn').setProperty('caption','Load from ' + env + ' SubVersion');
	zenPage.getComponentById('lblSetLbl1').setValue('1. Type Component, Namespace. Click on Load From SubVersion / Ensemble')

}
zenPage.getComponentById('butServer').setProperty('caption','Load from ' + env + ' Ensemble');

// if we need to know the cell # being drawn, we
// can get it vis grid.row and grid.column.
if (zenPage.getComponentById('buttonCheckIn').getProperty('hidden') == true)
{
	var r = grid.row;
	var c = grid.column;

	if (c == 2)
	{
		value2 = grid.getCellValue(r,1);
	}
	else
	{
		value2 = grid.getCellValue(r,2);
	}

	if (''==data) {
		return '&nbsp;';
	}
	else if (value2 != data) {

		return '<span style="color:red;">('+data+')</span>';
	}
}

return data;


