	var grid = zenPage.getComponentById('dynaGrid');
	var comp = zenPage.getComponentById('comp').getValue();
	var nmSp = zenPage.getComponentById('Namespace').getValue();

    if ((comp != '') && (nmSp!= ''))
    {
	   try
	    {
		    var env = zenPage.getComponentById('envRS').getValue();
		    if (src == 'Diff')
		    {
	   			zenPage.getComponentById('buttonCheckIn').setProperty('hidden', true);
	   			zenPage.getComponentById('butSave').setProperty('hidden', true);
	   			zenPage.getComponentById('lblAccess').setProperty('hidden', true);
	   			zenPage.getComponentById('CheckInComment').setProperty('hidden', true);


				var tempFile1 = zenPage.LoadSettingFile(comp, env, nmSp, 'Ensemble', 1, zenPage.getComponentById('lblAccess'));
				if (tempFile1.startsWith('ERROR') != true)
		   		{
			   		var tempFile2 = zenPage.LoadSettingFile(comp, env, nmSp, 'SVN', 1, zenPage.getComponentById('lblAccess'));
			   		if (tempFile2.startsWith('ERROR') != true)
		   			{
			   			this.GetDiffDataSet(grid, tempFile1, tempFile2, env, "replace");
			   			grid.setColumnProperty(1, 'readOnly', false)
			   			grid.set
		   			}
		   			else
			   		{ 		   			
		   				zenPage.getComponentById('lblAccess').setValue(tempFile2 )
		   				this.GetNewDataSet(grid, 'SVN FileNotFound', '', env, "replace");

			   		}
		   		}
		   		else
			   		{ 		   			
		   				zenPage.getComponentById('lblAccess').setValue(tempFile1 )
		   				this.GetNewDataSet(grid, 'Ensemble FileNotFound', '', env, "replace");

			   		}
		    }
  			else // From Ensemble or SVN
  			{
	  			zenPage.getComponentById('buttonCheckIn').setProperty('hidden', false);
	   			zenPage.getComponentById('butSave').setProperty('hidden', false);
	   			zenPage.getComponentById('lblAccess').setProperty('hidden', false);
	   			zenPage.getComponentById('CheckInComment').setProperty('hidden', false);

	   			var tempFile = zenPage.LoadSettingFile(comp, env, nmSp, src, 0, zenPage.getComponentById('lblAccess'));

		   		if (tempFile.startsWith('ERROR') != 0)
		   		{
		   			zenPage.getComponentById('lblAccess').setValue(tempFile )
		   			this.GetNewDataSet(grid, 'FileNotFound', src, env, "replace");
		   		}
		   		else
		   		{
			   		this.GetNewDataSet(grid, tempFile, src, env, "replace");
			   		grid.setColumnProperty(1, 'readOnly', true)
			   		if (src == 'SVN')
			   		{
				   		zenPage.getComponentById('lblAccess').setValue('Loaded ' + tempFile + ' from SubVersion')
			   		}
			   		else
			   		{ 		   			
			   			var sys = zenPage.getComponentById('systemLbl').getValue();
			   			zenPage.getComponentById('lblAccess').setValue('Loaded ' + tempFile + ' from Ensemble: ' + sys + ' - to modify for ' + env)
			   		}
		   		}
  			}

	    } catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception:  ' + err.message);
	    }
    }
    else
    {
	    zenPage.getComponentById('lblAccess').setValue('Component and Namespace  are required fields' );
    }

