set retStr = ""

try {

	set rStr = ""
	set comp = $ZSTRIP(comp,"<>WC")
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "LoadSettingFile: " _ comp _ ", " _ env _ ", Source: " _ src)
	set crFl =  ##class(IHC.ITF.SrcCtrlPkg.CreateSettingFiles).%New()

	set sc = crFl.createSettingsFile(nmSp, comp, env, src, $get(%session.Data("UsNm")), $get(%session.Data("PsWd")), .rStr, .tempFile)
	if ($$$ISOK(sc))
	{
		set retStr = "File for " _ comp _ " created: " _ sc _ "; " _ rStr
		if (ren = 1)
		{
			Do ##class(%File).Rename(tempFile, tempFile _ "-" _ src)
			set tempFile = tempFile _ "-" _ src
		}
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), tempFile _ " is created")
	}
	else
	{
		set retStr = "ERROR: Could not get setting file " _ sc
		set tempFile = "ERROR: Could not get setting file " _ sc
	}
} catch(err)
{
	set retStr = "Could not create setting files " _ err
}
