	Do pDataSet.%SetLabel("SubVersion " _ env ,2,2)

	set file = ##class(%File).%New(fileName1)
	set stat = file.Open("R")	

	if ($$$ISOK(stat))
	{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "Diff: " _ fileName1)
			set sc = $$$OK
			set rowId = 1
			while ('file.AtEnd)
			{
				set readStr = file.ReadLine(, .sc, .stat)
				If $$$ISERR(sc) 
					{ Do pDataSet.%SetValue("ERROR",r,1,1)  Quit }
				If stat { Quit }



				if ( ($L(readStr) > 0) && ($F(readStr, "#") '= 2) && ($F(readStr, "#$#") > 2))
				{
					        set typeStr = $ZSTRIP($PIECE(readStr, "#$#", 1),"<>W") 
					        set keyStr = $ZSTRIP($PIECE(readStr, "#$#", 2),"<>W")
					        set valueStr = $ZSTRIP($PIECE(readStr, "#$#", 3),"<>W")

					        Do pDataSet.%SetLabel(keyStr,rowId,1)
					        Do pDataSet.%SetValue(valueStr,rowId,1,1)


					        set file2 = ##class(%File).%New(fileName2)
							set stat = file2.Open("R")
							// Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "Open: " _ fileName2)
							while ('file2.AtEnd)
							{
								set readStr2 = file2.ReadLine(, .sc, .stat)
								If $$$ISERR(sc) 
									{ Do pDataSet.%SetValue("ERROR",r,1,1)  Quit }					
								If stat { Quit }

	   					         set typeStr2 = $ZSTRIP($PIECE(readStr2, "#$#", 1),"<>W") 

						         set keyStr2 = $ZSTRIP($PIECE(readStr2, "#$#", 2),"<>W")

						         set valueStr2 = $ZSTRIP($PIECE(readStr2, "#$#", 3),"<>W")
						         // Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "Diff: " _ typeStr _" = " _ typeStr2 _ " && " _ keyStr _" = " _ keyStr2)

						         if ( (typeStr = typeStr2) && (keyStr = keyStr2) )
						         {
						         	Do pDataSet.%SetValue(valueStr2,rowId,2,1)

						         	QUIT
						         }
							}
							Do file2.Close()
							// Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "Close: " _ fileName2)
					        set rowId = rowId + 1

				}

			}	
			Do file.Close()

} else
	{
		Do pDataSet.%SetLabel("-", 1,1)
		Do pDataSet.%SetValue("ERROR", 1,1,1)
		Do pDataSet.%SetValue(fileName1, 1,2,1)
	}
#;make sure grid gets redrawn
	Do pGrid.%ForceClientRender()

